1	package com.example.starter.pesticide;
2	
3	import com.example.starter.pesticide.dto.ApiDtos.BatchDetailResponse;
4	import com.example.starter.pesticide.dto.ApiDtos.LateEventView;
5	import com.example.starter.pesticide.dto.ApiDtos.ReportRequest;
6	import com.example.starter.pesticide.dto.ApiDtos.ReportResponse;
7	import com.example.starter.pesticide.dto.ApiDtos.SampleResponse;
8	import com.example.starter.pesticide.dto.ApiDtos.ReleaseResponse;
9	import com.example.starter.pesticide.dto.ApiDtos.TestView;
10	import org.springframework.dao.DuplicateKeyException;
11	import org.springframework.stereotype.Service;
12	import org.springframework.transaction.annotation.Transactional;
13	
14	import java.time.Clock;
15	import java.time.LocalDateTime;
16	import java.time.ZoneOffset;
17	import java.util.List;
18	
19	/**
20	 * 批次服务：产地报备、抽样、判定放行（判定与准入同事务）。
21	 */
22	@Service
23	public class BatchService {
24	
25	    private final BatchDao batchDao;
26	    private final TestDao testDao;
27	    private final LedgerDao ledgerDao;
28	    private final Clock clock;
29	
30	    public BatchService(BatchDao batchDao, TestDao testDao, LedgerDao ledgerDao, Clock clock) {
31	        this.batchDao = batchDao;
32	        this.testDao = testDao;
33	        this.ledgerDao = ledgerDao;
34	        this.clock = clock;
35	    }
36	
37	    /**
38	     * 产地报备：requestId 幂等，同键同参返回首次结果，同键异参 409；
39	     * 产地+品种+批次号唯一，并发报备仅一条受理；预警期间报备的批次加严抽检。
40	     */
41	    @Transactional
42	    public ReportResponse report(ReportRequest request) {
43	        String fingerprint = Fingerprint.of(request.requestId(), request.origin(), request.variety(),
44	                request.batchNo(), request.quantity().toPlainString());
45	        var existing = batchDao.findByRequestId(request.requestId());
46	        if (existing.isPresent()) {
47	            BatchDao.BatchRow row = existing.get();
48	            if (!row.fingerprint().equals(fingerprint)) {
49	                throw ApiException.conflict("requestId 已使用且业务字段不一致");
50	            }
51	            return toReportResponse(row, true);
52	        }
53	        String samplingLevel = ledgerDao.hasActiveAlert(request.origin(), request.variety())
54	                ? "STRICT" : "NORMAL";
55	        LocalDateTime now = nowUtc();
56	        try {
