22	@Service
23	public class TestService {
24	
25	    /** 疑似超标抑制率阈值（单位：%），达到即判疑似 */
26	    public static final BigDecimal SUSPECT_THRESHOLD = new BigDecimal("50");
27	    /** 处置结案留样时长（单位：小时） */
28	    public static final int RETENTION_HOURS = 48;
29	
30	    private final BatchDao batchDao;
31	    private final TestDao testDao;
