47	     */
48	    @Transactional
49	    public TestResponse rapidTest(TestRequest request) {
50	        String fingerprint = Fingerprint.of(request.requestId(), String.valueOf(request.batchId()),
51	                request.item(), request.inhibitionRate().toPlainString());
52	        var existing = testDao.findTestByRequestId(request.requestId());
53	        if (existing.isPresent()) {
54	            TestDao.TestRow row = existing.get();
55	            if (!row.fingerprint().equals(fingerprint)) {
56	                throw ApiException.conflict("requestId 已使用且业务字段不一致");
57	            }
58	            BatchDao.BatchRow batch = batchDao.findById(row.batchId()).orElseThrow();
59	            return toTestResponse(row, batch.status(), true, false);
60	        }
