62	                .orElseThrow(() -> ApiException.notFound("批次不存在: " + request.batchId()));
63	        BatchStatus status = BatchStatus.valueOf(batch.status());
64	        LocalDateTime now = nowUtc();
65	        if (status.isTerminal()) {
66	            ledgerDao.insertLateEvent(batch.id(), "LATE_TEST",
67	                    "item=" + request.item() + ", inhibitionRate=" + request.inhibitionRate(), now);
68	            return new TestResponse(null, request.requestId(), batch.id(), request.item(),
69	                    request.inhibitionRate(), null, batch.status(),
70	                    now.toInstant(ZoneOffset.UTC), false, true);
71	        }
72	        if (status == BatchStatus.FROZEN) {
73	            throw ApiException.conflict("批次疑似冻结待复检，同一批次同时刻只允许一条检测链");
74	        }
75	        if (!batchDao.sampleExists(batch.id(), request.item())) {
76	            throw ApiException.conflict("批次+项目未抽样，不得送检");
