82	                ? "SUSPECT" : "NORMAL";
83	        long testId;
84	        try {
85	            testId = testDao.insertTest(request.requestId(), fingerprint, batch.id(), request.item(),
86	                    request.inhibitionRate(), result, now);
87	        } catch (DuplicateKeyException e) {
88	            var raced = testDao.findTestByRequestId(request.requestId());
89	            if (raced.isPresent() && raced.get().fingerprint().equals(fingerprint)) {
90	                BatchDao.BatchRow current = batchDao.findById(batch.id()).orElseThrow();
91	                return toTestResponse(raced.get(), current.status(), true, false);
92	            }
93	            throw ApiException.conflict("批次+项目已检测，拒绝重复送检");
94	        }
95	        String batchStatus = batch.status();
96	        if ("SUSPECT".equals(result)) {
97	            batchDao.updateStatus(batch.id(), BatchStatus.FROZEN.name(), now);
98	            batchStatus = BatchStatus.FROZEN.name();
99	            alertService.maybeTrigger(batch.origin(), batch.variety(), now);
100	        }
101	        return new TestResponse(testId, request.requestId(), batch.id(), request.item(),
102	                request.inhibitionRate(), result, batchStatus, now.toInstant(ZoneOffset.UTC),
103	                false, false);
104	    }
