154	            batchDao.updateStatus(batch.id(), BatchStatus.DISPOSED.name(), now);
155	            batchStatus = BatchStatus.DISPOSED.name();
156	            retentionUntil = until.toInstant(ZoneOffset.UTC);
157	        }
158	        return new RecheckResponse(recheckId, request.requestId(), batch.id(), request.item(),
159	                request.qualified(), batchStatus, retentionUntil, now.toInstant(ZoneOffset.UTC),
160	                false, false);
