        sample(batchId, "有机磷");
        postJson("/api/tests", new TestRequest(testReqId, batchId, "有机磷", new BigDecimal("60")))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.result").value("SUSPECT"));
