                        + "       FROM joint_result WHERE order_id = ? GROUP BY item) latest"
                        + "   ON r.order_id = ? AND r.item = latest.item"
                        + "  AND r.result_version = latest.max_version"
                        + " ORDER BY r.item",
                RESULT_MAPPER, orderId, orderId);
    }

