        // 联检单详情：判定证据冻结
        mvc.perform(get("/api/joint/orders/" + orderId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("DETERMINED"))
                .andExpect(jsonPath("$.overallResult").value("PASS"))
