    @Test
    void 尚缺项目结果只能待定_不得判定() throws Exception {
        long[] frozen = frozenSuspectBatch("03");
        long orderId = createOrder("JC-03", frozen[0], frozen[1], "毒死蜱", "克百威");
        assign(orderId, "JA-03", 1L, "毒死蜱", "S-201", "AG-A", "克百威", "S-202", "AG-A");
