    @Test
    void 复测替换当前结果_保留旧版本_判定携带全部项版本() throws Exception {
        long[] frozen = frozenSuspectBatch("04");
        long orderId = createOrder("JC-04", frozen[0], frozen[1], "毒死蜱", "克百威");
        assign(orderId, "JA-04", 1L, "毒死蜱", "S-301", "AG-A", "克百威", "S-302", "AG-A");
