        postJson("/api/joint/determinations", detReq)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overallResult").value("PASS"));
        // 判定同键重放：返回首次冻结结果
        postJson("/api/joint/determinations", detReq)
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.replayed").value(true))
                .andExpect(jsonPath("$.overallResult").value("PASS"));
